import {cleanExperience,relationships,node,downloadFile,validDate} from './experience.js';
const starts={amor:'{para},\n\nTem uma história nossa em cada foto. Obrigado por estar ao meu lado e por transformar dias comuns em lembranças que eu quero guardar.\n\nCom amor,\n{de}',mae:'{para},\n\nHoje eu quis juntar um pouquinho do que sinto por você. Obrigado pelo cuidado, pelas histórias e por tanto carinho. Este mimo é seu.\n\nCom amor,\n{de}',pai:'{para},\n\nTem muita coisa sua nas minhas melhores lembranças. Obrigado por cada conversa, cada cuidado e cada momento que a gente viveu junto.\n\nCom carinho,\n{de}',avos:'{para},\n\nAlgumas lembranças têm o seu jeito: o abraço, as histórias e a vontade de ficar mais um pouco. Separei estas para a gente guardar.\n\nCom amor,\n{de}',amigo:'{para},\n\nA vida fica mais leve com você por perto. Estas fotos são só um pedacinho das histórias que a gente ainda vai contar.\n\nDa sua dupla,\n{de}',filho:'{para},\n\nEu queria guardar um pedacinho da alegria que é ter você na minha vida. Aqui estão algumas das nossas lembranças.\n\nCom todo o meu amor,\n{de}',pet:'{para},\n\nVocê bagunçou a casa e ganhou um lugar enorme no meu coração. Obrigado por cada chegada animada e cada companhia silenciosa.\n\nCom carinho,\n{de}',outro:'{para},\n\nEste é um jeito de dizer: que bom ter você por perto. Separei algumas lembranças e palavras que mereciam chegar até você.\n\nCom carinho,\n{de}'};
export function initExperienceEditor({getState,onChange,toast}){
 const $=s=>document.querySelector(s),patch=value=>onChange({experience:{...cleanExperience(getState().experience),...value}});
 const identity=node('section','experience-identity');identity.innerHTML='<div class="field"><label for="relationship">Para quem vai esse carinho?</label><select id="relationship"></select></div><div class="field"><label for="sender-name">De quem é o presente?</label><input id="sender-name" maxlength="60" autocomplete="given-name" placeholder="Seu nome"></div><div class="identity-dates"><div class="field"><label for="special-date">Uma data especial</label><input type="date" id="special-date"></div><div class="field"><label for="special-city">Cidade dessa lembrança</label><input id="special-city" maxlength="100" placeholder="Ex.: Belo Horizonte"></div></div>';$('.format-field').before(identity);for(const [key,profile] of Object.entries(relationships))$('#relationship').add(new Option(profile.label,key));
 const letter=node('details','letter-editor options-panel');letter.open=true;letter.innerHTML='<summary>Uma carta pra chamar de sua <span class="letter-count"></span></summary><p>Escreva do seu jeito. Pode ser uma frase, pode ser uma história inteira.</p><label for="personal-letter" class="sr-only">Sua carta</label><textarea id="personal-letter" maxlength="2000" rows="6" placeholder="Tem coisas que a gente guarda nas fotos. Outras, nas palavras…"></textarea><button type="button" class="letter-start">Me dá um começo</button>';$('#message').closest('.field').after(letter);
 const extras=node('details','extras-editor options-panel');extras.innerHTML='<summary>Detalhes que fazem o mimo ser seu</summary><p>Escolha só o que combina com a história de vocês.</p><div class="chapter-switches"><label><input type="checkbox" data-extra="counter"> Contador da data especial</label><label><input type="checkbox" data-extra="sky"> Céu simbólico da data</label><label><input type="checkbox" data-extra="reply"> Espaço para responder</label></div><details data-editor-list="timeline"><summary>Linha do tempo</summary><div class="extra-list"></div><button type="button" data-add-extra="timeline">＋ Adicionar momento</button></details><details data-editor-list="wheel"><summary>Roleta de pequenos planos</summary><p>Escreva pelo menos duas ideias para sortear.</p><div class="extra-list"></div><button type="button" data-add-extra="wheel">＋ Adicionar ideia</button></details><details class="secret-editor"><summary>Pergunta secreta</summary><label for="secret-hint">Uma pergunta que só vocês entendem</label><input id="secret-hint" maxlength="180" placeholder="Onde foi a nossa primeira viagem?"><label for="secret-answer">Resposta</label><input id="secret-answer" maxlength="100" autocomplete="off"><label for="secret-message">O que aparece ao acertar?</label><textarea id="secret-message" maxlength="1000" rows="3"></textarea><p>É uma brincadeira de adivinhação. Não use como senha ou para esconder informações sensíveis.</p></details><details data-editor-list="openWhen"><summary>Cartas “abra quando…”</summary><div class="extra-list"></div><button type="button" data-add-extra="openWhen">＋ Adicionar carta</button></details><details data-editor-list="collective"><summary>Recados da família e dos amigos</summary><p>Junte mensagens no mesmo presente. No modo local, você pode importar recados recebidos em arquivo.</p><div class="extra-list"></div><button type="button" data-add-extra="collective">＋ Adicionar recado</button><label class="import-note-label">Importar recado<input type="file" id="import-collective-note" accept="application/json,.json"></label><button type="button" class="download-note-invitation">Baixar convite para deixar um recado</button></details>';
 $('.customizer-bottom').before(extras);
 const bind=(id,key)=>$('#'+id).addEventListener('input',event=>patch({[key]:event.target.value}));bind('sender-name','sender');bind('special-city','city');bind('personal-letter','letter');$('#relationship').addEventListener('change',event=>patch({relationship:event.target.value}));$('#special-date').addEventListener('change',event=>{if(!event.target.value||validDate(event.target.value))patch({specialDate:event.target.value});});
 $('.letter-start').addEventListener('click',()=>{const ex=cleanExperience(getState().experience);if(ex.letter.trim()&&!confirm('Substituir a carta por um começo de exemplo?'))return;patch({letter:starts[ex.relationship].replaceAll('{para}',getState().recipient||'Você').replaceAll('{de}',ex.sender||'Alguém que te quer bem')});});
 extras.querySelectorAll('[data-extra]').forEach(input=>input.addEventListener('change',()=>patch({[input.dataset.extra]:input.checked})));
 for(const [id,key] of [['secret-hint','hint'],['secret-answer','answer'],['secret-message','message']])$('#'+id).addEventListener('input',event=>patch({secret:{...cleanExperience(getState().experience).secret,[key]:event.target.value}}));
 const limits={timeline:12,wheel:12,openWhen:8,collective:30};let lastLists='';
 function updateList(key,index,property,value){const list=[...cleanExperience(getState().experience)[key]];list[index]=key==='wheel'?value:{...list[index],[property]:value};patch({[key]:list});}
 function renderLists(ex){const focused=document.activeElement;if(focused?.closest('.extra-list')&&focused.matches('input,textarea'))return;const signature=JSON.stringify([ex.timeline,ex.wheel,ex.openWhen,ex.collective]);if(signature===lastLists)return;lastLists=signature;for(const key of Object.keys(limits)){const area=extras.querySelector('[data-editor-list="'+key+'"] .extra-list');area.replaceChildren();ex[key].forEach((entry,index)=>{const row=node('div','extra-row');let fields=key==='wheel'?[['','Ideia para sortear',80]]:key==='timeline'?[['when','Quando aconteceu?',40],['message','O que aconteceu?',240]]:key==='openWhen'?[['title','Abra quando…',100],['message','Sua mensagem',1000]]:[['name','Quem deixou o recado?',60],['message','Recado',1000]];for(const [property,label,max] of fields){const input=node(property==='message'?'textarea':'input');input.maxLength=max;input.placeholder=label;input.setAttribute('aria-label',label);input.value=key==='wheel'?entry:entry[property];if(input.tagName==='TEXTAREA')input.rows=3;input.addEventListener('input',()=>updateList(key,index,property,input.value));row.append(input);}const remove=node('button','remove-extra','Remover');remove.type='button';remove.addEventListener('click',()=>{const list=[...cleanExperience(getState().experience)[key]];list.splice(index,1);lastLists='';patch({[key]:list});});row.append(remove);area.append(row);});extras.querySelector('[data-add-extra="'+key+'"]').disabled=ex[key].length>=limits[key];}}
 extras.querySelectorAll('[data-add-extra]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.addExtra,ex=cleanExperience(getState().experience);if(ex[key].length>=limits[key])return;const entry=key==='wheel'?'':key==='timeline'?{when:'',message:''}:key==='openWhen'?{title:'Abra quando estiver com saudade',message:''}:{id:crypto.randomUUID(),name:'',message:''};lastLists='';patch({[key]:[...ex[key],entry]});}));
 function invitationHTML(){const id=getState().draftId,recipient=getState().recipient||'alguém especial';return '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Um recado para o mimo</title><style>body{font:18px system-ui;background:#fff6ea;color:#3a1e14;max-width:560px;margin:40px auto;padding:24px}input,textarea,button{font:inherit;display:block;width:100%;box-sizing:border-box;padding:14px;margin:12px 0;border:2px solid #3a1e14;border-radius:12px}button{background:#e8473a;color:white}p{line-height:1.6}</style><h1>Deixe um carinho.</h1><p id="about"></p><form><label>Seu nome<input required maxlength="60" id="name"></label><label>Seu recado<textarea required maxlength="1000" rows="6" id="note"></textarea></label><button>Baixar meu recado</button></form><p>Envie o arquivo baixado para quem está organizando o presente. Ele não é enviado automaticamente.</p><script>const gift='+JSON.stringify({id,recipient}).replaceAll('<','\\u003c')+';document.querySelector("#about").textContent="Vamos juntar mensagens para "+gift.recipient+". Escreva a sua e devolva o arquivo para quem convidou você.";document.querySelector("form").onsubmit=e=>{e.preventDefault();const payload={type:"capimimo-contribution",giftId:gift.id,id:crypto.randomUUID(),name:document.querySelector("#name").value.trim(),message:document.querySelector("#note").value.trim()};const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:"application/json"}));a.download="meu-recado-capimimo.json";a.click();};<\/script>';}
 $('.download-note-invitation').addEventListener('click',()=>downloadFile('convite-para-um-recado.html',new Blob([invitationHTML()],{type:'text/html;charset=utf-8'})));
 $('#import-collective-note').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>20000)throw Error();const note=JSON.parse(await file.text()),ex=cleanExperience(getState().experience);if(note.type!=='capimimo-contribution'||note.giftId!==getState().draftId||typeof note.name!=='string'||typeof note.message!=='string'||!note.message.trim()||note.message.length>1000)throw Error();if(ex.collective.some(row=>row.id===note.id)){toast('Esse recado já está no presente.');return;}if(ex.collective.length>=30)throw Error();lastLists='';patch({collective:[...ex.collective,{id:note.id||crypto.randomUUID(),name:note.name.slice(0,60),message:note.message}]});toast('Um novo carinho entrou no presente.');}catch{toast('Não foi possível importar. Confira se o recado pertence a este presente.');}event.target.value='';});
 function render(){const ex=cleanExperience(getState().experience);for(const [id,key] of [['sender-name','sender'],['special-date','specialDate'],['special-city','city'],['personal-letter','letter']])if(document.activeElement!==$('#'+id))$('#'+id).value=ex[key];$('#relationship').value=ex.relationship;identity.querySelector('label[for="special-date"]').textContent=relationships[ex.relationship].date;$('.letter-count').textContent=ex.letter.length+'/2000';extras.querySelectorAll('[data-extra]').forEach(input=>input.checked=ex[input.dataset.extra]);for(const [id,key] of [['secret-hint','hint'],['secret-answer','answer'],['secret-message','message']])if(document.activeElement!==$('#'+id))$('#'+id).value=ex.secret[key];renderLists(ex);}
 render();return {identity,letter,extras,render};
}
